using GymOS.Windows;
var checks=new(string cls,string name,string? expected)[]{("Camera","USB camera","camera"),("Image","Flatbed scanner",null),("Image","USB Webcam","camera"),("Keyboard","HID Keyboard Device","keyboard"),("HIDClass","USB Input Device","hid"),("HIDClass","Honeywell Barcode Reader","barcode"),("Biometric","Fingerprint sensor","biometric"),("AudioEndpoint","Speakers","audio"),("Ports","USB serial port","serial"),("DiskDrive","Customer backup",null),("Net","Camera-looking network adapter","networkAdapter"),("PrintQueue","Receipt printer","printer"),("SmartCardReader","USB smart card reader","smartCard"),("USBDevice","Unknown USB device","usb"),("Bluetooth","Bluetooth radio","bluetooth"),("Mystery","Barcode-looking label",null)};
foreach(var x in checks)if(DeviceInventory.Kind(x.cls,x.name)!=x.expected)throw new Exception("Classification failed: "+x.cls);
Console.WriteLine("16 native classification cases passed; detected is not integration-ready.");
if(OperatingSystem.IsWindows()){var rows=DeviceInventory.Enumerate();if(rows.Any(x=>x.id.Length!=24||x.name.Length>200||x.status!="detected"))throw new Exception("Invalid inventory");Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new{enumerated=rows.Length,byKind=rows.GroupBy(x=>x.kind).ToDictionary(x=>x.Key,x=>x.Count()),note="Read-only enumeration only. No scanner, camera or biometric integration was exercised."}));}

var origin="https://gymos-enterprise.vercel.app";var nonce=Guid.NewGuid().ToString();if(!DesktopCommands.DeviceInventoryAllowed(origin+"/",origin,nonce))throw new Exception("Trusted root rejected");foreach(var input in new[]{origin+".evil.test/",origin+"/sign-in","http://gymos-enterprise.vercel.app/","https://user:pass@gymos-enterprise.vercel.app/"})if(DesktopCommands.DeviceInventoryAllowed(input,origin,nonce))throw new Exception("Untrusted inventory source");if(DesktopCommands.DeviceInventoryAllowed(origin+"/",origin,"bad"))throw new Exception("Invalid request ID");foreach(var action in new[]{"devices","stopDevices","soundSettings"})if(!DesktopCommands.Allowed(action))throw new Exception("Known action rejected");if(DesktopCommands.Allowed("install-driver")||DesktopCommands.Allowed("run"))throw new Exception("Unknown command allowed");Console.WriteLine("Native request origin, nonce and command boundaries passed.");
